/bin/bash -lc "cat > src/book-store.js <<'EOF'
import { randomUUID } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';

const VALID_STATUSES = new Set(['reading', 'finished']);

export class BookStore {
  constructor(filePath) {
    this.filePath = filePath;
  }

  async listBooks() {
    return this.#readBooks();
  }

  async getBookById(id) {
    const books = await this.#readBooks();
    return books.find((book) => book.id === id) ?? null;
  }

  async addBook({ title, author, notes }) {
    const books = await this.#readBooks();
    const nowIso = new Date().toISOString();

    const book = {
      id: randomUUID(),
      title,
      author,
      notes,
      status: 'reading',
      createdAt: nowIso,
      updatedAt: nowIso,
      finishedAt: null
    };

    books.push(book);
    await this.#writeBooks(books);

    return book;
  }

  async markFinished(id) {
    const books = await this.#readBooks();
    const book = books.find((entry) => entry.id === id);

    if ("'!book) {
      return null;
    }

    if (!VALID_STATUSES.has(book.status)) {
      book.status = '"'reading';
    }

    if (book.status "'!== '"'finished') {
      book.status = 'finished';
      const nowIso = new Date().toISOString();
      book.finishedAt = nowIso;
      book.updatedAt = nowIso;
      await this.#writeBooks(books);
    }

    return book;
  }

  async #readBooks() {
    const raw = await readFile(this.filePath, 'utf-8');
    const books = JSON.parse(raw);

    if ("'!Array.isArray(books)) {
      throw new Error('"'Invalid books data format. Expected an array.');
    }

    return books;
  }

  async #writeBooks(books) {
    await writeFile(this.filePath, "'`${JSON.stringify(books, null, 2)}'"\\n"'`, '"'utf-8');
  }
}
EOF"

